import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/meeting.dart';
import '../../../data/repositories/group_repository.dart';
import '../../../l10n/app_localizations.dart';
import '../../widgets/app_drawer.dart';
class MeetingsScreen extends StatelessWidget{const MeetingsScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();final l=AppLocalizations.of(context);return Scaffold(appBar:AppBar(title:Text(l.t('meetings'))),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:StreamBuilder(stream:repo.meetings(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return Center(child:Text(l.t('loading')));if(s.hasError)return Center(child:Text('${l.t('error')}: ${s.error}'));final data=s.data??[];if(data.isEmpty)return Center(child:Text(l.t('noData')));return ListView(padding:const EdgeInsets.all(16),children:data.map((x)=>Card(child:ListTile(title:Text(x.agenda),subtitle:Text('${x.date}\n${x.decisions}')))).toList());}));}void _add(BuildContext context,GroupRepository repo){final l=AppLocalizations.of(context);final key=GlobalKey<FormState>();final agenda=TextEditingController();final decisions=TextEditingController();var loading=false;showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(context,setState)=>AlertDialog(title:Text(l.t('createMeeting')),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:agenda,decoration:InputDecoration(labelText:l.t('agenda')),validator:(v)=>(v==null||v.isEmpty)?l.t('required'):null),TextFormField(controller:decisions,decoration:InputDecoration(labelText:l.t('decisions')))])),actions:[FilledButton(onPressed:loading?null:()async{if(!key.currentState!.validate())return;setState(()=>loading=true);await repo.addMeeting(Meeting(id:'',date:DateTime.now(),agenda:agenda.text,decisions:decisions.text));if(context.mounted)Navigator.pop(context);},child:Text(loading?l.t('pleaseWait'):l.t('save')))])));}}
